TLM.f("Sancti/07-03r",{"officium":"S. Irenæi Episcopi et Martyris","rule":["vide C2;","Gloria","nocomm1960"],"fallback":"Commune/C2","sections":{"Introitus":[{"k":"ref","la":"Malach 2:6"},{"k":"text","la":"Lex veritátis fuit in ore ejus, et iníquitas non est invénta in lábiis ejus: in pace et in æquitáte ambulávit mecum, et multos avértit ab iniquitáte."},{"k":"ref","la":"Ps 77:1"},{"k":"text","la":"Atténdite, pópule meus, legem meam: inclináte aurem vestram in verba oris mei."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Lex veritátis fuit in ore ejus, et iníquitas non est invénta in lábiis ejus: in pace et in æquitáte ambulávit mecum, et multos avértit ab iniquitáte."}],"Oratio":[{"k":"text","la":"Deus, qui beáto Irenǽo Mártyri tuo atque Pontífici tribuísti, ut et veritáte doctrínæ expugnáret hǽreses, et pacem Ecclésiæ felíciter confirmáret: da, quǽsumus, plebi tuæ in sancta religióne constántiam; et pacem tuam nostris concéde tempóribus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"2 Tim 3:14-17; 4:1-5"},{"k":"text","la":"Caríssime: Pérmane in iis, quæ didicísti et crédita sunt tibi: sciens, a quo didíceris; et quia ab infántia sacras; lítteras nosti, quæ te possunt instrúere ad salútem, per fidem, quæ est in Christo Jesu. Omnis Scriptúra divínitus inspiráta útilis est ad docéndum, ad arguéndum, ad corripiéndum, ad erudiéndum in justítia: ut perféctus sit homo Dei, ad omne opus bonum instrúctus. Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prǽdica verbum, insta opportúne, importúne: árgue, óbsecra, íncrepa in omni patiéntia et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria coacervábunt sibi magístros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum imple."}],"Graduale":[{"k":"ref","la":"Ps 121:8"},{"k":"text","la":"Propter fratres meos et próximos meos loquébar pacem de te."},{"k":"ref","la":"Ps 36:37"},{"k":"text","la":"Custódi innocéntiam et vide æquitátem: quóniam sunt relíquiæ hómini pacífico."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli. 6:35"},{"k":"text","la":"In multitúdine presbyterórum prudéntium sta, et sapiéntiæ illórum ex corde conjúngere, ut omnem narratiónem Dei possis audíre. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 36:37"},{"k":"text","la":"Custódi innocéntiam et vide æquitátem: quóniam sunt relíquiæ hómini pacífico. Allelúja."},{"k":"ref","la":"Eccli 6:35"},{"k":"text","la":"In multitúdine presbyterórum prudéntium sta, et sapiéntiæ illórum ex corde conjúngere, ut omnem narratiónem Dei possis audire. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:23; 36:30-31"},{"k":"text","la":"Apud Dóminum gressus hóminis dirigéntur: et viam ejus volet."},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium.","mark":"V"},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 10:28-33"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nolíte timére eos, qui occídunt corpus, ánimam autem non possunt occídere; sed pótius timéte eum, qui potest et ánimam et corpus pérdere in gehénnam. Nonne duo pásseres asse véneunt: et unus ex illis non cadet super terram sine Patre vestro? Vestri autem capílli cápitis omnes numeráti sunt. Nolíte ergo timére: multis passéribus melióres estis vos. Omnis ergo, qui confitébitur me coram homínibus, confitébor et ego eum coram Patre meo, qui in cœlis est. Qui autem negáverit me coram homínibus, negábo et ego eum coram Patre meo, qui in cœlis est."}],"Offertorium":[{"k":"ref","la":"Eccli 24:44"},{"k":"text","la":"Doctrínam quasi ante lucánum illúmino ómnibus, et enarrábo illam usque ad longínquum."}],"Secreta":[{"k":"text","la":"Deus, qui credéntes in te pópulos nullis sinis cóncuti terróribus: dignáre preces et hóstias dicátæ tibi plebis suscípere; ut pax, a tua pietáte concéssa, christianórum fines ab omni hoste fáciat esse secúros."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Eccli 24:47"},{"k":"text","la":"Vidéte, quóniam non soli mihi laborávi, sed ómnibus exquiréntibus veritátem."}],"Postcommunio":[{"k":"text","la":"Deus, auctor pacis et amátor, quem nosse vívere, cui servíre regnáre est: prótege ab ómnibus impugnatiónibus súpplices tuos; ut, qui in defensióne tua confídimus, beáti Irenæi Mártyris tui atque Pontíficis intercessióne, nullius hostilitátis arma timeámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"636954c82d34cb2e":{"t":"Mal 2, 6, Ps 77, 1\n(Mal 2, 6) Zakon je istine bio u njegovim ustima, a na njegovim usnama nije bilo bezakonja. Mirno je i pravedno živio pređa mnom i mnoge je odvratio od grijeha. (Ps 77, 1) Čuj, puče moj, zakon moj, prigni uho svoje k riječima usta mojih.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mal 2, 6) Zakon je istine bio u njegovim ustima, a na njegovim usnama nije bilo bezakonja. Mirno je i pravedno živio pređa mnom i mnoge je odvratio od grijeha.","kn":"(Mal. 2, 6). Zakon je istine bio u ustima njegovim; živio je u miru sa mnom i, mnoge je obratio od opačine. (Ps. 119, 7) Među onima, koji mrze na mir, ja sam bio miroljubiv, kad im progovorim, navaljuju na me ni za što. Slava Ocu... Zakon ...","knRef":"Kniewald 1942, str. 612–613 (snimka 307) (OCR)"},"f5b215e0b8a7efe9":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženom Ireneju mučeniku svome i biskupu dao da i pravom naukom pobija krivovjerja i da sretno utvrdi mir Crkve, daj, molimo, svome narodu postojanost u svetoj vjeri i udijeli svoj mir našemu vremenu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si bi. Ireneju, mučeniku svome i biskupu, dao da i pravom naukom pobija krivovjerje i da uspješno učvrsti mir Crkve, podaj, molimo, puku svome stalnost u svetoj vjeri i našim vremenima udijeli svoj mir, po G. n.","knRef":"Kniewald 1942, str. 612–613 (snimka 307) (OCR)"},"33f77acabd8e228e":{"t":"2 Tim 3, 14-17; 4, 1-5\nČitanje Poslanice bl. Pavla apostola Timoteju. Predragi, ostani u onome što si naučio i što si prihvatio vjerom, znajući od koga si naučio, jer od djetinjstva poznaješ Sveto Pismo, koje te može po vjeri dovesti do spasa koji je u Isusu Kristu. Sve od Boga nadahnuto Pismo korisno je za pouku, dokazivanje, popravak i odgoj u pravdi, da Božji čovjek bude savršen, osposobljen za svako dobro djelo. Zaklinjem te pred Bogom i Isusom Kristom, koji će suditi živima i mrtvima, njegovim dolaskom i njegovim kraljevstvom: Propovijedaj nauku, revnuj u prikladno i neprikladno vrijeme, kori, prijeti, opominji strpljivo i poučno. Evo, dolazi vrijeme kada ljudi neće primati zdrave nauke, nego će prema svojim težnjama okupljati oko sebe učitelje koji će ini govoriti samo ono što im ugađa. Odvraćat će uši od istine, a slušati bajke. A ti bdij, sve trpi, propovijedaj evanđelje, vrši točno svoju službu.","kn":"Čitanje poslanice bi. Pavla apostola Timoteju (II. 3, 14, 17; 4, 1). Predragi! . Stoj u onomu, što si naučio, 4 što ti je povjereno, znajući, od kojih si naučio; 1 jer iz djetinjstva znaš Sveta Pisma, koji te mogu učiniti mudrim, na spasenje po vjeri, koja je u Isusu Kristu. Sve je Pismo Bogom nadahnuto i korisno za učenje, za dokazivanje, za , popravljanje, za odgoju u pravdi, da bude savršen čovjek Božji, spreman Za svako dobro djelo. Zaklinjem te pred Bogom i Kristom Isusom, koji će suditi žive i mrtve, i dolaskom njegovim i kraljevstvom njegovim. Propovijedaj riječ, nastoj u zgodno vrijerme, i u nevrijeme, pokaraj, zapriječi, umoli, učeći sa svom strpljivošju; jer će biti vrijeme, kad zdrave nauke ne će. primati, nego će Si pp svojim požudama nakupiti učitelje, jer ih Sv Irene) 28. VI. uši svrbe; I od vratit će uši od istine, a okrenut će se bajkama. A ti budi trijezan u svemu, trpi zlo, učini djelo evanđelista, službu svoju izvrši potpuno.","knRef":"Kniewald 1942, str. 612–613 (snimka 307) (OCR)"},"69a12f92073485f8":{"t":"Ps 121, 8, Ps 36, 37\n(Ps 121, 8) Radi braće svoje i radi prijatelja svojih velim: Mir tebi. (Ps 36, 37) Čuvaj nevinost i drži se pravednosti, jer će ostati samo miroljubivi naraštaj.\n\nSir 6, 35\n<i>Aleluja</i>, <i>aleluja</i>.\nŽivi u društvu razboritih starješina i srcem se pridruži njihovoj mudrosti, da možeš naučiti sve što govore o Bogu. <i>Aleluja</i>.","kn":"(Ps. 121, 8). Radi braće svoje i prijatelja svojih veiim: mir tebi. (Ps. 36, 37). Čuvaj nevinost i pazi na poštenje, jer će samo pokoljenje miroljubivih ostati.\n\nAleluja, aleluja. (Crkv. 6, 35). Prebivaj na društvu razboritih staraca i od srca se pridruži njihovoj mudrosti, da uzmogneš čuti sve, što govore o Bogu, aleluja.","knRef":"Kniewald 1942, str. 614–615 (snimka 308) (OCR)"},"5eea6b80d406f378":{"t":"Mt 10, 28-33\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Nemojte se bojati onih koji ubijaju tijelo, a ne mogu ubiti duše, nego se više bojte onoga koji može i dušu i tijelo baciti u pakao. Ne prodaju li se dva vrapca za jedan novčić? I ni jedan od njih neće pasti na zemlju bez vašeg Oca. A izbrojena je svaka vlas na vašoj glavi. Nemojte se, dakle, bojati jer ste vi vredniji od mnogo vrabaca. Svakoga, koji mene prizna pred ljudima, priznat ću i ja njega pred svojim nebeskim Ocem. A koji me zaniječe pred ljudima, neću ni ja njega priznati pred Ocem svojim nebeskim.","kn":"t Slijedi sv. evanđelje po Mateju (10, 28-33). U ono vrijeme reče Isus svojim učenicima: Ne bojte se onih, koji ubijaju tjelo, a duše ne mogu ubiti, nego Se više bojte onoga, koji može dušu 1 tijelo pogubiti u paklu. Ne prodaju li se dva vrapca za novčić? Pa ni jedan od njih ne će pasti na zemlju bez Oca vašega. A varna je i sva kosa na glavi izbrojena. Ne bojte se dakle! vi ste daleko vrijedniji od mnogo vrabaca. Kojigod dakle prizna mene pred ljudima, priznat ću i ja njega pred Ocem svojim, koji je na nebesima. A koji god zataji mene pred ljudima, zatajit ću i ja, njega pred Ocem svojim, koji je na nebesima.","knRef":"Kniewald 1942, str. 614–615 (snimka 308) (OCR)"},"9da5d5f840d0e140":{"t":"Sir 24, 44\nŠirim nauku kao što se širi rumenilo jutarnje zore. Naviještam je svima sve do u daljine.","kn":"(Crkv. 24, 44). Moja nauka svijetli kao jutarnje rumenilo i ja je naviještam u daljine.","knRef":"Kniewald 1942, str. 614–615 (snimka 308) (OCR)"},"524a676e80b26616":{"t":"Bože, koji ne dopuštaš da se narodi koji u te vjeruju preplaše bilo kakvim strahom, udostoji se primiti molitve i darove naroda tebi posvećenoga, da mir što ga ti u svojoj dobroti daješ osigura kršćanske zemlje od svakog neprijatelja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji ne dopuštaš, da ikakav strah pritište Tvoj vjerni puk, dostoj se primiti molitve i žrtve puka, koji je Tebi posvećen, da mir, što ga Ti u svojoj blagosti daješ, učini kršćanske zemlje sigurnima od svakog neprijatelja, po G n.","knRef":"Kniewald 1942, str. 614–615 (snimka 308) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"8d035c4bb6d2427e":{"t":"Sir 24, 47\nVidite da se nisam trudio samo za sebe nego za sve koji traže istinu.","kn":"(Crkv. 24, 47). Vidite, da nisam za se radio, nego za sve, koji traže Istinu.","knRef":"Kniewald 1942, str. 614–615 (snimka 308) (OCR)"},"b3d5bc726603a162":{"t":"<i>Pomolimo se</i>.\nBože, začetniče i ljubitelju mira, koga poznavati znači živjeti, kojemu služiti znači kraljevati, one koji ti se mole štiti od svih navala, da se po zagovoru blaženog Ireneja mučenika tvoga i biskupa ne bojimo nikakvoga neprijateljskog oružja, jer se uzdamo u tvoju obranu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Bože, početniče i ljubitelju mira. Tebe poznavati znači živjeti, a Tebi služiti znači kraljevati: štiti od svih navala one, koji se utječu Tebi, da se zagovorom bi. Ireneja, mučenika Tvoga i biskupa, ne bojimo nikakvog neprijateljskog oružja, po G. n.","knRef":"Kniewald 1942, str. 614–615 (snimka 308) (OCR)"}}});
